#!/usr/bin/env bash
# Builds the workspace before the agent starts. claude plugin eval runs it
# only under --scaffold, with the empty workspace as the working directory.
set -euo pipefail
mkdir -p docs/llm-orchestrator/specs
printf '%s' '' | base64 -d > docs/llm-orchestrator/specs/2026-08-04-csv-export-spec.md
git init -q 2>/dev/null || true
git add -A 2>/dev/null || true
git -c user.email=e@e -c user.name=e commit -qm 'baseline: approved csv export spec' 2>/dev/null || true
